css:
/* The handoff's full location card, measured from its .loc--full rules. Colours
   are the design-system roles the handoff names: its red is `accent`. */
[data-bz-section="location-list"] > .bz-section { padding-block: 90px }
[data-bz-section="location-list"] .bz-block { padding-block: 0 }
[data-bz-section="location-list"] .bz-block + .bz-block { padding-block-start: 0 }
[data-bz-section="location-list"] .bz-row + .bz-row { margin-top: 0 }

/* The band's heading is for screen readers only: the handoff runs the cards
   straight on from the map above, and the h2 keeps the outline h2 → h3. */
[data-bz-section="location-list"] [data-bz-node="ll-head"] {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0;
  overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; border: 0;
}

[data-bz-section="location-list"] [data-bz-node="ll-grid"] { --bz-gap: 24px }
[data-bz-section="location-list"] .bz-col[data-bz-node^="ll-card-"] {
  display: flex; flex-direction: column;
  background: var(--card); border: 1px solid var(--line); border-radius: 0; padding: 30px 26px;
}
[data-bz-section="location-list"] [data-bz-node^="ll-card-h"] .bz-eyebrow {
  font: 700 10px/1.3 var(--font-body); letter-spacing: .14em; text-transform: uppercase;
  color: var(--accent); margin: 0 0 12px;
}
[data-bz-section="location-list"] [data-bz-node^="ll-card-h"] h3 {
  font: 800 21px/1.7 var(--font-heading); letter-spacing: 0; color: var(--ink); margin: 0 0 6px;
}
[data-bz-section="location-list"] [data-bz-node^="ll-card-addr"] p {
  font-size: 14px; line-height: 1.6; color: var(--muted); margin: 0 0 18px;
}
/* One paragraph per department, each ruled off above like the handoff's list. */
[data-bz-section="location-list"] [data-bz-node^="ll-card-hours"] .bz-text {
  display: flex; flex-direction: column; gap: 8px; margin: 0 0 18px;
}
[data-bz-section="location-list"] [data-bz-node^="ll-card-hours"] p {
  font-size: 14px; line-height: 1.5; color: var(--body-text); margin: 0;
  border-top: 1px solid var(--line); padding-top: 8px;
}
[data-bz-section="location-list"] [data-bz-node^="ll-card-perks"] p {
  font-size: 13px; line-height: 1.55; color: var(--muted); margin: 0 0 18px;
}
/* Phones and directions sit on the card floor, so a row of cards with
   different amounts of copy lines its links up. */
[data-bz-section="location-list"] [data-bz-node^="ll-card-cta"] { margin-top: auto }
[data-bz-section="location-list"] [data-bz-node^="ll-card-cta"] + [data-bz-node^="ll-card-links"] { padding-block-start: 8px }
[data-bz-section="location-list"] [data-bz-node^="ll-card-links"]:only-child,
[data-bz-section="location-list"] [data-bz-node^="ll-card-perks"] + [data-bz-node^="ll-card-links"],
[data-bz-section="location-list"] [data-bz-node^="ll-card-hours"] + [data-bz-node^="ll-card-links"],
[data-bz-section="location-list"] [data-bz-node^="ll-card-addr"] + [data-bz-node^="ll-card-links"] { margin-top: auto }
[data-bz-section="location-list"] .bz-btns {
  margin-block: 0; gap: 8px; flex-direction: column; align-items: flex-start;
}
[data-bz-section="location-list"] .bz-btn--link {
  font: 700 15px/1.7 var(--font-body); letter-spacing: 0; text-transform: none;
  color: var(--accent); text-decoration: none;
}
[data-bz-section="location-list"] .bz-btn--link:hover { text-decoration: underline; text-underline-offset: 3px }

@media (max-width: 1100px) {
  [data-bz-section="location-list"] .bz-col[data-bz-node^="ll-card-"] { grid-column: span 6 / span 6 }
}
@media (max-width: 640px) {
  [data-bz-section="location-list"] .bz-col[data-bz-node^="ll-card-"] { grid-column: 1 / -1 }
}
